CREATE TABLE app_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(160) NOT NULL UNIQUE, display_name VARCHAR(80) NOT NULL, password_hash VARCHAR(100) NOT NULL);
CREATE TABLE course (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(120) NOT NULL, description VARCHAR(1000) NOT NULL);
CREATE TABLE course_member (course_id BIGINT NOT NULL, user_id BIGINT NOT NULL, role VARCHAR(20) NOT NULL, PRIMARY KEY(course_id,user_id), FOREIGN KEY(course_id) REFERENCES course(id), FOREIGN KEY(user_id) REFERENCES app_user(id));
CREATE TABLE assignment (id BIGINT AUTO_INCREMENT PRIMARY KEY, course_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, requirements VARCHAR(4000) NOT NULL, due_at VARCHAR(40) NOT NULL, rubric_version VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(course_id) REFERENCES course(id));
CREATE TABLE entry (id BIGINT AUTO_INCREMENT PRIMARY KEY, assignment_id BIGINT NOT NULL, author_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, draft_json LONGTEXT NOT NULL, evidence_json LONGTEXT NOT NULL, revision INT NOT NULL DEFAULT 0, updated_at VARCHAR(40) NOT NULL, UNIQUE(assignment_id,author_id), FOREIGN KEY(assignment_id) REFERENCES assignment(id), FOREIGN KEY(author_id) REFERENCES app_user(id));
CREATE TABLE submission (id BIGINT AUTO_INCREMENT PRIMARY KEY, entry_id BIGINT NOT NULL, version_no INT NOT NULL, title VARCHAR(160) NOT NULL, content_json LONGTEXT NOT NULL, content_hash VARCHAR(64) NOT NULL, rubric_version VARCHAR(40) NOT NULL, idempotency_key VARCHAR(80) NOT NULL, created_at VARCHAR(40) NOT NULL, UNIQUE(entry_id,version_no), UNIQUE(entry_id,idempotency_key), FOREIGN KEY(entry_id) REFERENCES entry(id));
CREATE TABLE evaluation (id BIGINT AUTO_INCREMENT PRIMARY KEY, submission_id BIGINT NOT NULL, teacher_id BIGINT NOT NULL, revision_no INT NOT NULL, details_json LONGTEXT NOT NULL, dimensions_json LONGTEXT NOT NULL, q_raw DECIMAL(9,4), q_final DECIMAL(9,4), gate_reason VARCHAR(1000) NOT NULL, summary VARCHAR(2000) NOT NULL, active BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL, UNIQUE(submission_id,revision_no), FOREIGN KEY(submission_id) REFERENCES submission(id));
CREATE TABLE feedback (id BIGINT AUTO_INCREMENT PRIMARY KEY, submission_id BIGINT NOT NULL, teacher_id BIGINT NOT NULL, paragraph_id VARCHAR(80) NOT NULL, original_text VARCHAR(4000) NOT NULL, indicator_code VARCHAR(8) NOT NULL, body VARCHAR(2000) NOT NULL, resolved BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(submission_id) REFERENCES submission(id));
CREATE TABLE feedback_action (id BIGINT AUTO_INCREMENT PRIMARY KEY, feedback_id BIGINT NOT NULL, user_id BIGINT NOT NULL, action_type VARCHAR(20) NOT NULL, body VARCHAR(2000) NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(feedback_id) REFERENCES feedback(id));
CREATE TABLE evidence (id BIGINT AUTO_INCREMENT PRIMARY KEY, submission_id BIGINT NOT NULL, paragraph_id VARCHAR(80) NOT NULL, source_title VARCHAR(300) NOT NULL, source_url VARCHAR(2000) NOT NULL, excerpt VARCHAR(4000) NOT NULL, claim_text VARCHAR(2000) NOT NULL, state VARCHAR(20) NOT NULL, FOREIGN KEY(submission_id) REFERENCES submission(id));
CREATE TABLE verification (id BIGINT AUTO_INCREMENT PRIMARY KEY, evidence_id BIGINT NOT NULL, verifier_id BIGINT NOT NULL, verdict VARCHAR(20) NOT NULL, reason VARCHAR(2000) NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(evidence_id) REFERENCES evidence(id));
CREATE TABLE publication (id BIGINT AUTO_INCREMENT PRIMARY KEY, submission_id BIGINT NOT NULL UNIQUE, author_id BIGINT NOT NULL, state VARCHAR(20) NOT NULL, requested_at VARCHAR(40) NOT NULL, reviewed_at VARCHAR(40), reviewer_id BIGINT, FOREIGN KEY(submission_id) REFERENCES submission(id));
CREATE TABLE audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT NOT NULL, action_type VARCHAR(80) NOT NULL, resource_type VARCHAR(40) NOT NULL, resource_id BIGINT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE INDEX idx_entry_assignment ON entry(assignment_id);
CREATE INDEX idx_submission_entry ON submission(entry_id,version_no);
CREATE INDEX idx_evaluation_submission ON evaluation(submission_id,active);
CREATE INDEX idx_feedback_submission ON feedback(submission_id);
CREATE INDEX idx_evidence_submission ON evidence(submission_id);
